rules.logic:
element.style.flex = '1 1 auto';
element.style.maxWidth = '100%';
element.style.width = '100%';

const container = element.querySelector('.vector-typeahead-search-container');
if (container) {
  container.style.width = '100%';
  container.style.maxWidth = '100%';
}

const form = element.querySelector('.cdx-search-input');
if (form) {
  form.style.width = '100%';
  form.style.maxWidth = '100%';
}

const inputWrapper = element.querySelector('.cdx-search-input__input-wrapper');
if (inputWrapper) {
  inputWrapper.style.width = '100%';
}
